args <- commandArgs(trailingOnly=TRUE); if(!length(args)) stop("Usage: Rscript scripts/inspect_smoke_download.R <downloaded-path>")
invisible(lapply(list.files("R",pattern="\\.R$",full.names=TRUE),source)); path<-normalizePath(args[[1]],mustWork=TRUE); cat("actual file type:",tolower(tools::file_ext(path)),"\n"); ncs<-discover_netcdf_files(path); cat("NetCDF files discovered:",paste(ncs,collapse=", "),"\n"); if(!length(ncs)) quit(status=0); for(nc in ncs) { x<-inspect_netcdf_file(nc); cat("NetCDF:",nc,"\nvariables:",paste(x$variables,collapse=", "),"\ndimensions:",paste(x$dimensions,collapse=" x "),"\nlayer count:",x$dimensions[["layers"]],"\nCRS:",x$crs,"\ntime:",paste(x$time,collapse=", "),"\n") }
